import React, { useState, useEffect } from 'react';
import { Search, ShoppingCart, Film, Calendar, DollarSign, Star, X, LogOut, User } from 'lucide-react';

const MovieRentalSystem = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [isSignUp, setIsSignUp] = useState(false);
  const [signUpForm, setSignUpForm] = useState({ name: '', email: '', password: '', confirmPassword: '' });

  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('All');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [showCart, setShowCart] = useState(false);

  const genres = ['All', 'Sci-Fi', 'Crime', 'Action', 'Drama', 'Animation', 'Fantasy', 'Romance', 'Adventure', 'Comedy'];

  // Fetch movies from backend
  useEffect(() => {
    fetch('http://localhost:8080/api/movies')
      .then(res => res.json())
      .then(data => {
        const formatted = data.map(m => ({
          id: m.movieID,
          title: m.title,
          genre: m.genre,
          year: m.year,
          rating: m.rating,
          price: m.defaultPrice,
          description: m.description,
          duration: m.duration
        }));
        setMovies(formatted);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching movies:', err);
        // Fallback to hardcoded data if backend fails
        setMovies([
          { id: 1, title: 'Inception', genre: 'Sci-Fi', year: 2010, rating: 8.8, price: 5.00, description: 'A mind-bending thriller', duration: 148 },
          { id: 2, title: 'The Matrix', genre: 'Sci-Fi', year: 1999, rating: 8.7, price: 5.00, description: 'A computer hacker discovers reality', duration: 136 },
          { id: 3, title: 'Interstellar', genre: 'Sci-Fi', year: 2014, rating: 8.6, price: 6.00, description: 'Exploring space and time', duration: 169 },
          { id: 4, title: 'The Godfather', genre: 'Crime', year: 1972, rating: 9.2, price: 8.00, description: 'Crime family saga', duration: 175 },
          { id: 5, title: 'The Dark Knight', genre: 'Action', year: 2008, rating: 9.0, price: 5.00, description: 'Batman faces the Joker', duration: 152 },
          { id: 6, title: 'Pulp Fiction', genre: 'Crime', year: 1994, rating: 8.9, price: 6.00, description: 'Crime stories intertwined', duration: 154 },
          { id: 7, title: 'Forrest Gump', genre: 'Drama', year: 1994, rating: 8.8, price: 5.00, description: 'Life story of Forrest Gump', duration: 142 },
          { id: 8, title: 'Gladiator', genre: 'Action', year: 2000, rating: 8.5, price: 6.00, description: 'Roman general seeks revenge', duration: 155 },
          { id: 9, title: 'Titanic', genre: 'Romance', year: 1997, rating: 7.9, price: 7.00, description: 'Shipwreck romance', duration: 195 },
          { id: 10, title: 'Avatar', genre: 'Sci-Fi', year: 2009, rating: 7.8, price: 7.00, description: 'Humans explore Pandora', duration: 162 },
          { id: 11, title: 'Jurassic Park', genre: 'Adventure', year: 1993, rating: 8.2, price: 5.00, description: 'Dinosaurs brought back to life', duration: 127 },
          { id: 12, title: 'The Avengers', genre: 'Action', year: 2012, rating: 8.0, price: 6.00, description: 'Superheroes unite', duration: 143 },
          { id: 13, title: 'Toy Story', genre: 'Animation', year: 1995, rating: 8.3, price: 4.00, description: 'Animated toys adventure', duration: 81 },
          { id: 14, title: 'The Lion King', genre: 'Animation', year: 1994, rating: 8.5, price: 4.00, description: 'Animated lion prince story', duration: 88 },
          { id: 15, title: 'Finding Nemo', genre: 'Animation', year: 2003, rating: 8.2, price: 5.00, description: 'Clownfish lost in ocean', duration: 100 },
          { id: 16, title: 'Star Wars: A New Hope', genre: 'Sci-Fi', year: 1977, rating: 8.6, price: 5.00, description: 'Space opera adventure', duration: 121 },
          { id: 17, title: 'Star Wars: Empire Strikes Back', genre: 'Sci-Fi', year: 1980, rating: 8.7, price: 5.00, description: 'Darker chapter of saga', duration: 124 },
          { id: 18, title: 'The Lord of the Rings: Fellowship', genre: 'Fantasy', year: 2001, rating: 8.8, price: 6.00, description: 'Fantasy epic begins', duration: 178 },
          { id: 19, title: 'The Lord of the Rings: Two Towers', genre: 'Fantasy', year: 2002, rating: 8.7, price: 6.00, description: 'Second part of epic', duration: 179 },
          { id: 20, title: 'The Lord of the Rings: Return of the King', genre: 'Fantasy', year: 2003, rating: 8.9, price: 6.00, description: 'Final epic battle', duration: 201 },
          { id: 21, title: 'Harry Potter and the Sorcerers Stone', genre: 'Fantasy', year: 2001, rating: 7.6, price: 5.00, description: 'Boy wizard discovers magic', duration: 152 },
          { id: 22, title: 'Harry Potter and the Chamber of Secrets', genre: 'Fantasy', year: 2002, rating: 7.4, price: 5.00, description: 'Second year at Hogwarts', duration: 161 },
          { id: 23, title: 'Frozen', genre: 'Animation', year: 2013, rating: 7.4, price: 4.00, description: 'Animated princess adventure', duration: 102 },
          { id: 24, title: 'Coco', genre: 'Animation', year: 2017, rating: 8.4, price: 4.00, description: 'Musical journey of a boy', duration: 105 },
          { id: 25, title: 'Moana', genre: 'Animation', year: 2016, rating: 7.6, price: 5.00, description: 'Polynesian princess adventure', duration: 107 },
          { id: 26, title: 'Avengers: Endgame', genre: 'Action', year: 2019, rating: 8.4, price: 6.00, description: 'Heroes fight Thanos', duration: 181 },
          { id: 27, title: 'Black Panther', genre: 'Action', year: 2018, rating: 7.3, price: 6.00, description: 'Marvel superhero in Wakanda', duration: 134 },
          { id: 28, title: 'Spider-Man: No Way Home', genre: 'Action', year: 2021, rating: 8.2, price: 6.00, description: 'Spider-Man multiverse adventure', duration: 148 },
          { id: 29, title: 'Guardians of the Galaxy', genre: 'Action', year: 2014, rating: 8.0, price: 5.00, description: 'Space adventurers unite', duration: 121 },
          { id: 30, title: 'Deadpool', genre: 'Comedy', year: 2016, rating: 8.0, price: 4.00, description: 'Merc with a mouth', duration: 108 }
        ]);
        setLoading(false);
      });
  }, []);

  const handleLogin = (e) => {
    e.preventDefault();
    if (loginForm.email && loginForm.password) {
      setCurrentUser({ email: loginForm.email, name: loginForm.email.split('@')[0] });
      setIsLoggedIn(true);
      setLoginForm({ email: '', password: '' });
    }
  };

  const handleSignUp = (e) => {
    e.preventDefault();
    if (signUpForm.name && signUpForm.email && signUpForm.password === signUpForm.confirmPassword) {
      setCurrentUser({ email: signUpForm.email, name: signUpForm.name });
      setIsLoggedIn(true);
      setSignUpForm({ name: '', email: '', password: '', confirmPassword: '' });
      setIsSignUp(false);
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    setCart([]);
  };

  const addToCart = (movie) => {
    if (!cart.find(item => item.id === movie.id)) {
      setCart([...cart, { ...movie, rentalDays: 3 }]);
    }
  };

  const removeFromCart = (id) => {
    setCart(cart.filter(item => item.id !== id));
  };

  const updateRentalDays = (id, days) => {
    setCart(cart.map(item => 
      item.id === id ? { ...item, rentalDays: parseInt(days) } : item
    ));
  };

  const filteredMovies = movies.filter(movie => {
    const matchesSearch = movie.title.toLowerCase().includes(search.toLowerCase());
    const matchesGenre = selectedGenre === 'All' || movie.genre === selectedGenre;
    return matchesSearch && matchesGenre;
  });

  const totalPrice = cart.reduce((sum, item) => sum + (item.price * item.rentalDays), 0);

  // Login Page
  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 flex items-center justify-center p-4">
        <div className="max-w-md w-full">
          <div className="text-center mb-8">
            <div className="flex items-center justify-center gap-2 mb-4">
              <Film className="w-12 h-12 text-red-500" />
              <h1 className="text-4xl font-bold text-white">MovieFlix</h1>
            </div>
            <p className="text-gray-400">Your favorite movies, just a click away</p>
          </div>

          <div className="bg-gray-800 rounded-lg shadow-xl p-8">
            <div className="flex gap-2 mb-6">
              <button
                onClick={() => setIsSignUp(false)}
                className={`flex-1 py-2 rounded-lg font-semibold transition ${
                  !isSignUp ? 'bg-red-600 text-white' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                Login
              </button>
              <button
                onClick={() => setIsSignUp(true)}
                className={`flex-1 py-2 rounded-lg font-semibold transition ${
                  isSignUp ? 'bg-red-600 text-white' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                Sign Up
              </button>
            </div>

            {!isSignUp ? (
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Email</label>
                  <input
                    type="email"
                    required
                    value={loginForm.email}
                    onChange={(e) => setLoginForm({ ...loginForm, email: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="your@email.com"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Password</label>
                  <input
                    type="password"
                    required
                    value={loginForm.password}
                    onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="••••••••"
                  />
                </div>
                <button
                  onClick={handleLogin}
                  className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded-lg transition"
                >
                  Login
                </button>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Name</label>
                  <input
                    type="text"
                    required
                    value={signUpForm.name}
                    onChange={(e) => setSignUpForm({ ...signUpForm, name: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="John Doe"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Email</label>
                  <input
                    type="email"
                    required
                    value={signUpForm.email}
                    onChange={(e) => setSignUpForm({ ...signUpForm, email: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="your@email.com"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Password</label>
                  <input
                    type="password"
                    required
                    value={signUpForm.password}
                    onChange={(e) => setSignUpForm({ ...signUpForm, password: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="••••••••"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">Confirm Password</label>
                  <input
                    type="password"
                    required
                    value={signUpForm.confirmPassword}
                    onChange={(e) => setSignUpForm({ ...signUpForm, confirmPassword: e.target.value })}
                    className="w-full px-4 py-3 bg-gray-700 border border-gray-600 rounded-lg focus:outline-none focus:border-red-500 text-white"
                    placeholder="••••••••"
                  />
                </div>
                {signUpForm.password && signUpForm.confirmPassword && signUpForm.password !== signUpForm.confirmPassword && (
                  <p className="text-red-500 text-sm">Passwords do not match</p>
                )}
                <button
                  onClick={handleSignUp}
                  className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded-lg transition"
                >
                  Sign Up
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Main App
  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center">
        <h2 className="text-xl">Loading movies...</h2>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <header className="bg-gray-800 border-b border-gray-700 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Film className="w-8 h-8 text-red-500" />
            <h1 className="text-2xl font-bold">MovieFlix Rentals</h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 text-gray-300">
              <User className="w-5 h-5" />
              <span className="hidden sm:inline">{currentUser?.name}</span>
            </div>
            <button
              onClick={() => setShowCart(!showCart)}
              className="flex items-center gap-2 bg-red-600 hover:bg-red-700 px-4 py-2 rounded-lg transition"
            >
              <ShoppingCart className="w-5 h-5" />
              <span>Cart ({cart.length})</span>
            </button>
            <button
              onClick={handleLogout}
              className="flex items-center gap-2 bg-gray-700 hover:bg-gray-600 px-4 py-2 rounded-lg transition"
            >
              <LogOut className="w-5 h-5" />
              <span className="hidden sm:inline">Logout</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search movies..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-gray-800 border border-gray-700 rounded-lg focus:outline-none focus:border-red-500"
            />
          </div>
          <div className="flex gap-2 flex-wrap">
            {genres.map(genre => (
              <button
                key={genre}
                onClick={() => setSelectedGenre(genre)}
                className={`px-4 py-2 rounded-lg transition ${
                  selectedGenre === genre
                    ? 'bg-red-600 text-white'
                    : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
                }`}
              >
                {genre}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {filteredMovies.map(movie => (
            <div
              key={movie.id}
              className="bg-gray-800 rounded-lg overflow-hidden hover:transform hover:scale-105 transition cursor-pointer"
              onClick={() => setSelectedMovie(movie)}
            >
              <div className="bg-gray-700 h-48 flex items-center justify-center text-6xl">
                🎬
              </div>
              <div className="p-4">
                <h3 className="font-bold text-lg mb-2">{movie.title}</h3>
                <div className="flex items-center justify-between text-sm text-gray-400 mb-3">
                  <span>{movie.genre}</span>
                  <div className="flex items-center gap-1">
                    <Star className="w-4 h-4 fill-yellow-500 text-yellow-500" />
                    <span>{movie.rating}</span>
                  </div>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-red-500 font-bold">${movie.price}/day</span>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      addToCart(movie);
                    }}
                    className="bg-red-600 hover:bg-red-700 px-3 py-1 rounded text-sm transition"
                  >
                    Add to Cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {selectedMovie && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center p-4 z-20">
          <div className="bg-gray-800 rounded-lg max-w-2xl w-full p-6">
            <div className="flex justify-between items-start mb-4">
              <h2 className="text-2xl font-bold">{selectedMovie.title}</h2>
              <button onClick={() => setSelectedMovie(null)}>
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="space-y-4">
              <div className="text-6xl text-center py-8 bg-gray-700 rounded">
                🎬
              </div>
              <p className="text-gray-300">{selectedMovie.description}</p>
              <div className="flex gap-4 text-sm">
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" />
                  <span>{selectedMovie.year}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Star className="w-4 h-4 fill-yellow-500 text-yellow-500" />
                  <span>{selectedMovie.rating}/10</span>
                </div>
                <div className="flex items-center gap-2">
                  <DollarSign className="w-4 h-4" />
                  <span>${selectedMovie.price}/day</span>
                </div>
              </div>
              <button
                onClick={() => {
                  addToCart(selectedMovie);
                  setSelectedMovie(null);
                }}
                className="w-full bg-red-600 hover:bg-red-700 py-3 rounded-lg font-bold transition"
              >
                Add to Cart
              </button>
            </div>
          </div>
        </div>
      )}

      {showCart && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-30" onClick={() => setShowCart(false)}>
          <div
            className="absolute right-0 top-0 h-full w-full max-w-md bg-gray-800 shadow-xl overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">Your Cart</h2>
                <button onClick={() => setShowCart(false)}>
                  <X className="w-6 h-6" />
                </button>
              </div>
              
              {cart.length === 0 ? (
                <p className="text-gray-400 text-center py-8">Your cart is empty</p>
              ) : (
                <>
                  <div className="space-y-4 mb-6">
                    {cart.map(item => (
                      <div key={item.id} className="bg-gray-700 p-4 rounded-lg">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="font-bold">{item.title}</h3>
                          <button
                            onClick={() => removeFromCart(item.id)}
                            className="text-red-500 hover:text-red-400"
                          >
                            <X className="w-5 h-5" />
                          </button>
                        </div>
                        <div className="flex items-center gap-4">
                          <label className="text-sm text-gray-400">Rental Days:</label>
                          <input
                            type="number"
                            min="1"
                            max="30"
                            value={item.rentalDays}
                            onChange={(e) => updateRentalDays(item.id, e.target.value)}
                            className="w-20 px-2 py-1 bg-gray-600 rounded"
                          />
                        </div>
                        <div className="mt-2 text-right">
                          <span className="text-red-500 font-bold">
                            ${(item.price * item.rentalDays).toFixed(2)}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                  
                  <div className="border-t border-gray-600 pt-4">
                    <div className="flex justify-between items-center mb-4">
                      <span className="text-xl font-bold">Total:</span>
                      <span className="text-2xl font-bold text-red-500">
                        ${totalPrice.toFixed(2)}
                      </span>
                    </div>
                    <button className="w-full bg-red-600 hover:bg-red-700 py-3 rounded-lg font-bold transition">
                      Proceed to Checkout
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MovieRentalSystem;
